from tool import Object_Detector_Tool

def count_tennis_rackets(figure):
    image_path = figure
    labels = ["baseball", "basket"]
    model_size = "tiny"
    threshold = 0.3
    padding = 20

    detection = Object_Detector_Tool.execute(image=image_path, labels=labels, threshold=threshold, model_size=model_size, padding=padding).output_type
    if detection != None:
        tennis_rackets = [obj for obj in detection if obj['confidence score'] > 0.9]
        if tennis_rackets:
            return len(tennis_rackets)
        else:
            return 0
    else:
        return 0
